function esc(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

function extractText(message) {
  if (!message) return '';
  return (
    message.conversation ||
    message.extendedTextMessage?.text ||
    message.imageMessage?.caption ||
    message.videoMessage?.caption ||
    message.buttonsResponseMessage?.selectedDisplayText ||
    message.listResponseMessage?.title ||
    ''
  ).trim();
}

// O node Webhook do n8n entrega a requisição crua: { headers, params, query, body }.
// Os dados da mensagem do Evolution API vêm dentro de body.data.
const item = $input.item.json;
const body = item.body || item;
const data = body.data || {};
const key = data.key || {};
const msg = data.message || {};

const messageText = extractText(msg);
const messageId = key.id || null;
const conversationId = key.remoteJid || null;
const contactName = data.pushName || null;
const isSupport = key.fromMe === true;
const messageTimestamp = data.messageTimestamp
  ? new Date(Number(data.messageTimestamp) * 1000).toISOString()
  : new Date().toISOString();

const sqlQuery = `INSERT INTO support_messages (message_id, conversation_id, contact_name, is_support, message_text, message_timestamp)
VALUES (${esc(messageId)}, ${esc(conversationId)}, ${esc(contactName)}, ${isSupport ? 'TRUE' : 'FALSE'}, ${esc(messageText)}, ${esc(messageTimestamp)})
ON CONFLICT (message_id) DO NOTHING;`;

return {
  json: {
    message_id: messageId,
    conversation_id: conversationId,
    contact_name: contactName,
    is_support: isSupport,
    message_text: messageText,
    message_timestamp: messageTimestamp,
    sql_query: sqlQuery,
  },
};
